        public GradleSetup(IDiagnosticLogger logger, string gradleProjectPath)
        {
            _logger = logger;
            _unityLibraryGradle = Path.Combine(gradleProjectPath, "unityLibrary", "build.gradle");
        }

        public void UpdateGradleProject()
        {
            _logger.LogInfo("Adding Sentry to the gradle project.");
            var unityLibraryGradleContent = LoadGradleScript(_unityLibraryGradle);
            unityLibraryGradleContent = AddSentryToGradle(unityLibraryGradleContent);
            File.WriteAllText(_unityLibraryGradle, unityLibraryGradleContent);
        }

        public void ClearGradleProject()
        {
            _logger.LogInfo("Removing Sentry from the gradle project.");
            var unityLibraryGradleContent = LoadGradleScript(_unityLibraryGradle);
            unityLibraryGradleContent = RemoveFromGradleContent(unityLibraryGradleContent);
            File.WriteAllText(_unityLibraryGradle, unityLibraryGradleContent);
        }

        internal string AddSentryToGradle(string gradleContent)
        {
            if (gradleContent.Contains(SdkDependenciesFull))
            {
                _logger.LogDebug(DependenciesAddedMessage);
                return gradleContent;
            }

            var androidMarkerIndex = gradleContent.IndexOf(AndroidMarker, StringComparison.Ordinal);
            if (androidMarkerIndex == -1)
            {
                _logger.LogError($"Failed to find '{AndroidMarker}' to add the Sentry Gradle dependencies.");
                return gradleContent;
            }

            return gradleContent.Remove(androidMarkerIndex, AndroidMarker.Length).Insert(androidMarkerIndex, SdkDependenciesFull);
        }

        internal string RemoveFromGradleContent(string gradleContent)
        {
            if (gradleContent.Contains(SdkDependenciesFull))
            {
                var dependenciesFullIndex = gradleContent.IndexOf(SdkDependenciesFull, StringComparison.Ordinal);
                return gradleContent.Remove(dependenciesFullIndex, SdkDependenciesFull.Length).Insert(dependenciesFullIndex, AndroidMarker);
            }

            _logger.LogDebug(DependenciesAddedMessage);
            return gradleContent;
        }

        internal static string LoadGradleScript(string path)
        {
            if (!File.Exists(path))
            {
                throw new FileNotFoundException($"Failed to find the gradle config.", path);
            }
            return File.ReadAllText(path);
        }
    }
}
